import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

import { DELETED_WORKSPACE_RETENTION_DAYS } from "@/config/constants";
import { emit, subscribe } from "@/lib/event-bus";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { PermissionDeniedError } from "@/lib/permissions";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as invitationRepo from "@/server/repositories/invitation-repository";
import * as webhookRepo from "@/server/repositories/webhook-repository";
import { runCleanupArchivedJob } from "@/server/jobs/cleanup-archived-job";
import { runWebhookDeliveryJob } from "@/server/jobs/webhook-delivery-job";
import { notify } from "@/server/services/notification-service";
import { acceptInvitation } from "@/server/services/invitation-service";
import { NotFoundError } from "@/server/services/_support";
import {
  deleteOrganization,
  restoreOrganization,
} from "@/server/services/organization-service";
import { listActivity, registerActivityListeners } from "@/server/services/activity-service";
import { createTenant, useTemporaryDatabase } from "./server/_support/fixtures";
import type { Tenant } from "./server/_support/fixtures";
import type { Unsubscribe } from "@/types/event";

let cleanup: () => void;
let detach: Unsubscribe;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detach = registerActivityListeners();
});

afterAll(() => {
  detach();
  cleanup();
});

describe("sanity: deleted workspace retention", () => {
  it("delete -> restore round trip publishes events and audit rows", async () => {
    const tenant: Tenant = await createTenant("sanity-restore");

    const deletedSeen: string[] = [];
    const restoredSeen: string[] = [];
    const offD = subscribe("organization.deleted", (p) => deletedSeen.push(p.slug));
    const offR = subscribe("organization.restored", (p) => restoredSeen.push(p.slug));

    const deleted = await deleteOrganization(tenant.actors.owner, {
      orgId: tenant.org.id,
      confirmSlug: tenant.org.slug,
    });
    expect(deleted.archivedAt).not.toBeNull();
    expect(deletedSeen).toEqual([tenant.org.slug]);

    // double delete -> AlreadyArchivedError
    await expect(
      deleteOrganization(tenant.actors.owner, {
        orgId: tenant.org.id,
        confirmSlug: tenant.org.slug,
      }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);

    // non-owner member cannot restore
    await expect(
      restoreOrganization(tenant.userIds.admin, tenant.org.id),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    // non-member cannot restore -> NotFoundError
    await expect(
      restoreOrganization("01HZZZNOBODYNOBODYNOBODYNO" as never, tenant.org.id),
    ).rejects.toBeInstanceOf(NotFoundError);

    const restored = await restoreOrganization(tenant.userIds.owner, tenant.org.id);
    expect(restored.archivedAt).toBeNull();
    expect(restoredSeen).toEqual([tenant.org.slug]);

    // restoring an already-live org is a no-op, publishes nothing
    const again = await restoreOrganization(tenant.userIds.owner, tenant.org.id);
    expect(again.archivedAt).toBeNull();
    expect(restoredSeen).toEqual([tenant.org.slug]);

    const page = await listActivity(tenant.actors.owner, {
      orgId: tenant.org.id,
      action: ["organization.deleted", "organization.restored"],
      limit: 25,
      cursor: null,
    });
    expect(page.items.map((e) => e.action).sort()).toEqual(
      ["organization.deleted", "organization.restored"].sort(),
    );

    offD();
    offR();
  });

  it("restore throws NotFoundError once the retention window has closed", async () => {
    const tenant: Tenant = await createTenant("sanity-window");

    await deleteOrganization(tenant.actors.owner, {
      orgId: tenant.org.id,
      confirmSlug: tenant.org.slug,
    });

    const future = new Date(
      Date.now() + (DELETED_WORKSPACE_RETENTION_DAYS + 1) * 24 * 60 * 60 * 1000,
    );
    vi.useFakeTimers();
    vi.setSystemTime(future);
    try {
      await expect(
        restoreOrganization(tenant.userIds.owner, tenant.org.id),
      ).rejects.toBeInstanceOf(NotFoundError);
    } finally {
      vi.useRealTimers();
    }
  });

  it("the retention sweep purges a workspace past its window and leaves a fresh one alone", async () => {
    const tenant: Tenant = await createTenant("sanity-purge");
    const live: Tenant = await createTenant("sanity-live-alone");

    await deleteOrganization(tenant.actors.owner, {
      orgId: tenant.org.id,
      confirmSlug: tenant.org.slug,
    });

    const future = new Date(
      Date.now() + (DELETED_WORKSPACE_RETENTION_DAYS + 1) * 24 * 60 * 60 * 1000,
    );

    const result = await runCleanupArchivedJob(future);
    expect(result.failed).toBe(0);

    expect(await orgRepo.findOrgById(tenant.org.id)).toBeNull();
    expect(await memberRepo.findMember(tenant.org.id, tenant.userIds.owner)).toBeNull();

    await expect(
      restoreOrganization(tenant.userIds.owner, tenant.org.id),
    ).rejects.toBeInstanceOf(NotFoundError);

    // the live org (never deleted) is untouched by the same sweep
    expect(await orgRepo.findOrgById(live.org.id)).not.toBeNull();
  });

  it("a pending invitation into a deleted workspace cannot be accepted", async () => {
    const tenant: Tenant = await createTenant("sanity-invite");

    const invitation = await invitationRepo.insertInvitation(
      tenant.org.id,
      { orgId: tenant.org.id, email: "new@sanity-invite.test", role: "member", expiresInDays: 14 },
      tenant.userIds.owner,
      "hashed-token-sanity",
    );

    await deleteOrganization(tenant.actors.owner, {
      orgId: tenant.org.id,
      confirmSlug: tenant.org.slug,
    });

    await expect(
      acceptInvitation(tenant.userIds.viewer, { token: "irrelevant" }),
