import { runCleanupArchivedJob } from "@/server/jobs/cleanup-archived-job";
import { runWebhookDeliveryJob } from "@/server/jobs/webhook-delivery-job";
import { notify } from "@/server/services/notification-service";
import { acceptInvitation } from "@/server/services/invitation-service";
import { NotFoundError } from "@/server/services/_support";
import {
  deleteOrganization,
  restoreOrganization,
} from "@/server/services/organization-service";
import { listActivity, registerActivityListeners } from "@/server/services/activity-service";
import { createTenant, useTemporaryDatabase } from "./server/_support/fixtures";
import type { Tenant } from "./server/_support/fixtures";
import type { Unsubscribe } from "@/types/event";

let cleanup: () => void;
let detach: Unsubscribe;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detach = registerActivityListeners();
});

afterAll(() => {
  detach();
  cleanup();
});

describe("sanity: deleted workspace retention", () => {
  it("delete -> restore round trip publishes events and audit rows", async () => {
    const tenant: Tenant = await createTenant("sanity-restore");

    const deletedSeen: string[] = [];
    const restoredSeen: string[] = [];
    const offD = subscribe("organization.deleted", (p) => deletedSeen.push(p.slug));
    const offR = subscribe("organization.restored", (p) => restoredSeen.push(p.slug));

    const deleted = await deleteOrganization(tenant.actors.owner, {
      orgId: tenant.org.id,
      confirmSlug: tenant.org.slug,
    });
    expect(deleted.archivedAt).not.toBeNull();
    expect(deletedSeen).toEqual([tenant.org.slug]);

    // double delete -> AlreadyArchivedError
    await expect(
      deleteOrganization(tenant.actors.owner, {
        orgId: tenant.org.id,
        confirmSlug: tenant.org.slug,
      }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);

    // non-owner member cannot restore
    await expect(
      restoreOrganization(tenant.userIds.admin, tenant.org.id),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    // non-member cannot restore -> NotFoundError
    await expect(
      restoreOrganization("01HZZZNOBODYNOBODYNOBODYNO" as never, tenant.org.id),
    ).rejects.toBeInstanceOf(NotFoundError);

    const restored = await restoreOrganization(tenant.userIds.owner, tenant.org.id);
    expect(restored.archivedAt).toBeNull();
    expect(restoredSeen).toEqual([tenant.org.slug]);

    // restoring an already-live org is a no-op, publishes nothing
    const again = await restoreOrganization(tenant.userIds.owner, tenant.org.id);
    expect(again.archivedAt).toBeNull();
    expect(restoredSeen).toEqual([tenant.org.slug]);

    const page = await listActivity(tenant.actors.owner, {
      orgId: tenant.org.id,
      action: ["organization.deleted", "organization.restored"],
