    const invitation = await invitationRepo.insertInvitation(
      tenant.org.id,
      { orgId: tenant.org.id, email: "new@sanity-invite.test", role: "member", expiresInDays: 14 },
      tenant.userIds.owner,
      "hashed-token-sanity",
    );

