      "member_joined",
      [tenant.userIds.owner],
      { title: "t", body: "b", href: "/x", actorId: null },
    );
    expect(rows).toEqual([]);
  });

  it("webhook deliveries for a deleted workspace are marked failed, not delivered", async () => {
    const tenant: Tenant = await createTenant("sanity-webhook", "growth");

    const endpoint = await webhookRepo.insertEndpoint(
      { orgId: tenant.org.id, url: "https://example.test/hook", eventTypes: ["issue.created"] },
      "secret",
    );
    await webhookRepo.enqueueDelivery(
      tenant.org.id,
